pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address payable alice = payable(address(0x123));
        vm.deal(address(c), 1 ether);
        vm.deal(address(this), 1 ether);
        bytes memory emptyData;
        vm.prank(address(this));
        c.Command{value: 1 ether}(alice, emptyData);
        assertEq(alice.balance, 1 ether);
    }
}
